import{_ as a,o as n,c as i,a3 as l}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-45 — Form tạo phiên đấu giá (admin)","description":"","frontmatter":{"title":"SC-45 — Form tạo phiên đấu giá (admin)"},"headers":[],"relativePath":"wireframes/admin/sc-45-form-tao-phien.md","filePath":"wireframes/admin/sc-45-form-tao-phien.md","lastUpdated":1791606799000}'),t={name:"wireframes/admin/sc-45-form-tao-phien.md"};function c(p,s,e,o,d,h){return n(),i("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-45-—-form-tao-phien-đau-gia-admin" tabindex="-1">SC-45 — Form tạo phiên đấu giá (admin) <a class="header-anchor" href="#sc-45-—-form-tao-phien-đau-gia-admin" aria-label="Permalink to &quot;SC-45 — Form tạo phiên đấu giá (admin)&quot;">​</a></h1><p><span class="wf-badge danger">ADMIN</span> <span class="wf-badge info">Route: /admin/dau-gia/create</span> <span class="wf-badge muted">Nguồn: docs/05 §3 · docs/06 endpoint 55/57 · docs/08 BR-AU-01..04/06/09 · docs/03 UC-11 · docs/02 FR-AU-01/02</span></p><p><strong>Ai xem màn này</strong>: ADMIN vận hành đấu giá. Vào từ nút &quot;+ Tạo phiên&quot; ở SC-44 (hoặc click dòng DRAFT để sửa cấu hình). <strong>Mục đích</strong>: form một màn tạo phiên DRAFT với <strong>đầy đủ validate ràng buộc nghiệp vụ tại field</strong> — bước giá 1–20% khởi điểm, cọc 1–20% + min 10.000.000 ₫, giờ mở ≥ +7 ngày, đóng đăng ký <strong>tự tính = mở − 24h (readonly)</strong>. Sai ở đâu báo ở đó, không cho submit rồi mới lỗi. <strong>Ví dụ số dùng trong bản vẽ</strong>: căn <code>CT2-A18.05</code> dự án NOXH <code>HP-380</code> (72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng) · giá rao <code>1.250.000.000 ₫</code> · khởi điểm nhập <code>1.800.000.000 ₫</code> · bước <code>18.000.000 ₫</code> (1%) · cọc 5% = <code>90.000.000 ₫</code> · phí 1,5%.</p><h2 id="_1-desktop-—-form-tao-phien-gia-tri-hop-le" tabindex="-1">1. Desktop — form tạo phiên (giá trị hợp lệ) <a class="header-anchor" href="#_1-desktop-—-form-tao-phien-gia-tri-hop-le" aria-label="Permalink to &quot;1. Desktop — form tạo phiên (giá trị hợp lệ)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/admin/dau-gia/create</span></div><div class="wf-body"><div class="wf-row" style="align-items:stretch;gap:0;"><div class="wf-admin-rail"><span class="brand">AnPhuc Admin</span><span class="item">Dashboard</span><span class="item">KYC</span><span class="item">Tin</span><span class="item">Dự án</span><span class="item active">Đấu giá</span><span class="item">Thanh toán</span><span class="item">Người dùng</span><span class="item">Audit</span></div><div class="wf-grow wf-col" style="padding:16px;min-width:0;gap:12px;"><div class="wf-row between middle"><span class="wf-title lg">Tạo phiên đấu giá <span class="wf-callout">1</span></span><span class="wf-small wf-accent">← Quay lại danh sách SC-44</span></div><div class="wf-row" style="align-items:flex-start;gap:16px;"><div class="wf-grow wf-col" style="gap:14px;min-width:0;"><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Tin đăng (chỉ tin LISTED, chưa có phiên đang sống) <span class="wf-callout">2</span></span><div class="wf-input filled">CT2-A18.05 — NOXH HP-380 · 72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng<span class="caret">▾</span></div><span class="wf-small wf-muted">Giá rao 1.250.000.000 ₫ · chủ nhà Nguyễn Văn A (KYC APPROVED ✓) · pháp lý đã xác minh</span></div><div class="wf-row" style="gap:12px;"><div class="wf-col wf-grow" style="gap:4px;"><span class="wf-small wf-strong">Giá khởi điểm (VND, ≥ 100.000.000) <span class="wf-callout">3</span></span><div class="wf-input filled"><span class="wf-money">1.800.000.000 ₫</span><span class="caret">✎</span></div><span class="wf-small wf-muted">Gợi ý = giá rao 1.250.000.000 ₫ — có thể sửa</span></div><div class="wf-col wf-grow" style="gap:4px;"><span class="wf-small wf-strong">Bước giá (VND) <span class="wf-callout">4</span></span><div class="wf-input filled"><span class="wf-money">18.000.000 ₫</span><span class="caret">✎</span></div><span class="wf-small wf-muted">= 1% khởi điểm · cho phép 18.000.000 – 360.000.000 (1–20%)</span></div></div><div class="wf-row" style="gap:12px;"><div class="wf-col wf-grow" style="gap:4px;"><span class="wf-small wf-strong">Tỷ lệ cọc (%) <span class="wf-callout">5</span></span><div class="wf-input filled">5 %<span class="caret">✎</span></div><span class="wf-small wf-muted">1–20% · mặc định 5%</span></div><div class="wf-col wf-grow" style="gap:4px;"><span class="wf-small wf-strong">Phí đấu giá (%) <span class="wf-callout">6</span></span><div class="wf-input filled">1,5 %<span class="caret">✎</span></div><span class="wf-small wf-muted">0–5% · mặc định 1,5%</span></div></div><div class="wf-row" style="gap:12px;"><div class="wf-col wf-grow" style="gap:4px;"><span class="wf-small wf-strong">Thời gian mở phiên <span class="wf-callout">7</span></span><div class="wf-input filled">17/10/2026 09:00 (GMT+7)<span class="caret">🗓</span></div><span class="wf-small wf-ok-text">✓ Hợp lệ — cách hiện tại 7 ngày 2 giờ (tối thiểu +7 ngày)</span></div><div class="wf-col wf-grow" style="gap:4px;"><span class="wf-small wf-strong">Thời gian kết thúc (dự kiến)</span><div class="wf-input filled">17/10/2026 15:00 (GMT+7)<span class="caret">🗓</span></div><span class="wf-small wf-muted">Sau giờ mở, tổng thời lượng ≤ 24h · thực tế kết thúc theo anti-snipe</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Đóng đăng ký <span class="wf-callout">8</span></span><div class="wf-input" style="background:var(--wf-fill);color:var(--wf-ink-soft);">16/10/2026 09:00 (GMT+7) — tự động = giờ mở − 24h 🔒</div><span class="wf-small wf-muted">Readonly — hệ thống tính, không sửa được; sau mốc này endpoint đăng ký trả 410</span></div></div><div class="wf-sidebar wf-col" style="gap:10px;width:280px;"><span class="wf-title">Tóm tắt cấu hình <span class="wf-callout">9</span></span><div class="wf-row between"><span class="wf-text">Khởi điểm</span><span class="wf-money">1.800.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Bước giá</span><span class="wf-money">18.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Cọc mỗi người (5%)</span><span class="wf-money">90.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Phí trúng giá (1,5%)</span><span class="wf-money">~27.000.000 ₫</span></div><div class="wf-row between" style="border-top:1px solid var(--wf-line);padding-top:6px;"><span class="wf-text">Giá tối thiểu nếu trúng</span><span class="wf-strong">khởi điểm + phí − cọc</span></div><div class="wf-note" style="margin:0;">Cọc tự tính <b>floor(1.800.000.000 × 5%) = 90.000.000 ₫</b> — không dưới 10.000.000 ₫. Mọi phép tiền làm tròn xuống, số nguyên VND. <span class="ref">BR-AU-06/14</span></div><div class="wf-col" style="gap:8px;margin-top:4px;"><span class="wf-btn primary lg block">Lưu &amp; Công bố ngay <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">10</span></span><span class="wf-btn block">Lưu nháp (DRAFT)</span><span class="wf-btn ghost block">Hủy bỏ</span></div></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/02 FR-AU-01/02 · docs/08 BR-AU · docs/03 UC-11)</div><ol><li><span class="num">1</span><span>Form 1 màn, không wizard (admin power-user, ít bước). Validate <b>onBlur + onSubmit</b>, message tại field, chuỗi lỗi một nguồn. <span class="ref">docs/05 §1.5</span></span></li><li><span class="num">2</span><span>Dropdown tin chỉ chứa tin <b>LISTED</b> không có phiên đang sống (DRAFT/PUBLISHED/IN_PROGRESS) — tìm theo unitCode/tên dự án. Tin đã RESERVED/SOLD hoặc đã vào phiên khác bị loại (server vẫn re-check, 409 nếu race). <span class="ref">BR-AU-02</span> <span class="ref">UC-11 precondition</span></span></li><li><span class="num">3</span><span>Khởi điểm: integer VND ≥ 100.000.000 (CHECK DB ≥ 1e8). Nhập liệu format VND tự ngắt chấm khi gõ. Gợi ý = giá rao, <b>editable</b> theo UC-11 MF-1. <span class="ref">FR-AU-01</span></span></li><li><span class="num">4</span><span><b>Bước giá validate 1–20% khởi điểm</b> (CHECK DB floor(opening×1%) → floor(opening×20%)); hint cập nhật realtime theo opening. Bất biến sau publish — sửa ở DRAFT thoải mái. <span class="ref">BR-AU-09</span></span></li><li><span class="num">5</span><span><b>Cọc validate 1–20%, min 10.000.000 ₫</b>: input là %, sidebar hiện số tiền suy ra; nếu floor(opening×pct) &lt; 10tr → field error ngay (xem mục 2). <span class="ref">BR-AU-06</span></span></li><li><span class="num">6</span><span>Phí đấu giá 0–5%, default 1,5 — dùng tính payable khi AWARDED (floor). <span class="ref">BR-AU-14</span></span></li><li><span class="num">7</span><span><b>Giờ mở ≥ +7 ngày</b> kể từ lúc công bố (BR-AU-03 kiểm tại publish, notice_at = now): FE chặn sớm với message tại field; server re-check khi &quot;Lưu &amp; Công bố&quot; → 422 <code>NOTICE_TOO_SHORT</code>. DatePicker chặn ngày quá khứ. <span class="ref">BR-AU-03</span> <span class="ref">UC-11 EF-1</span></span></li><li><span class="num">8</span><span><b>Đóng đăng ký = mở − 24h, auto-computed + readonly</b> (icon 🔒 = placeholder, thay icon thật) — không cho admin tự đặt mốc vô lý; sau mốc này registration endpoint → 410 <code>AUCTION_REG_CLOSED</code>. <span class="ref">BR-AU-04</span></span></li><li><span class="num">9</span><span>Sidebar tóm tắt <b>tính live</b> theo input (cọc, phí, khoảng bước giá cho phép) — quy tắc &quot;không số gộp&quot;: admin thấy ngay số tiền thật người mua sẽ cọc. <span class="ref">docs/05 §1.6</span></span></li><li><span class="num">10</span><span><b>Hai nút lưu</b>: &quot;Lưu nháp&quot; → POST tạo DRAFT, toast ok <b>&quot;Tạo phiên DGA-2026-0012 (DRAFT) thành công — chưa hiển thị public&quot;</b>, redirect SC-44. &quot;Lưu &amp; Công bố&quot; → tạo + publish: tin LISTED→RESERVED, hiện SC-05, mở đăng ký; toast <b>&quot;Công bố phiên DGA-2026-0012 — tin CT2-A18.05 chuyển RESERVED&quot;</b>. Cả hai → audit <code>AUCTION_CREATE</code>/<code>AUCTION_PUBLISH</code>. Đang gửi → nút loading disabled. <span class="ref">FR-AU-01/02</span> <span class="ref">endpoint 55/57</span> <span class="ref">BR-ADM-01</span></span></li></ol></div><h2 id="_2-bien-the-loi-—-validate-inline-tai-field-khong-đoi-submit" tabindex="-1">2. Biến thể lỗi — validate inline tại field (không đợi submit) <a class="header-anchor" href="#_2-bien-the-loi-—-validate-inline-tai-field-khong-đoi-submit" aria-label="Permalink to &quot;2. Biến thể lỗi — validate inline tại field (không đợi submit)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-body"><div class="wf-container" style="max-width:720px;"><span class="wf-state-label">SUBMIT VỚI 4 FIELD SAI — 422/400 MAPPING TẠI FIELD</span><div class="wf-col" style="gap:14px;margin-top:8px;"><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Thời gian mở phiên</span><div class="wf-input error filled">12/10/2026 09:00 (GMT+7)<span class="caret">🗓</span></div><span class="wf-field-error">Giờ mở phải cách thời điểm công bố tối thiểu 7 ngày — sớm nhất 17/10/2026 11:00 <span class="wf-callout danger">11</span></span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Bước giá (VND)</span><div class="wf-input error filled"><span class="wf-money">9.000.000 ₫</span><span class="caret">✎</span></div><span class="wf-field-error">Bước giá phải từ 1% đến 20% giá khởi điểm (18.000.000 ₫ – 360.000.000 ₫) <span class="wf-callout danger">12</span></span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Tỷ lệ cọc (%)</span><div class="wf-input error filled">3 %<span class="caret">✎</span></div><span class="wf-field-error">Cọc tối thiểu 10.000.000 ₫ — với khởi điểm 200.000.000 ₫, 3% chỉ = 6.000.000 ₫. Tăng tỷ lệ hoặc tăng giá khởi điểm <span class="wf-callout danger">13</span></span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Thời gian kết thúc (dự kiến)</span><div class="wf-input error filled">19/10/2026 09:00 (GMT+7)<span class="caret">🗓</span></div><span class="wf-field-error">Kết thúc phải sau giờ mở và tổng thời lượng phiên ≤ 24 giờ</span></div><div class="wf-error-box" style="text-align:left;padding:12px;"><b>4 trường cần sửa trước khi lưu</b> <span class="wf-small">— cuộn tới lỗi đầu tiên, focus field, nút lưu giữ nguyên (không disable) để admin thấy vì sao. Server trả 400 <code>VALIDATION_ERROR</code> với <code>errors[]</code> theo field nếu FE lọt lưới.</span><br><span class="wf-trace">traceId: 8b1d40aa-c2e5-4f61</span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span>Lỗi giờ mở dùng logic <code>NOTICE_TOO_SHORT</code> (422 khi publish): message nêu <b>mốc sớm nhất cụ thể</b> (now + 7 ngày) để admin sửa ngay một lần, không đoán. <span class="ref">BR-AU-03</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">12</span><span>Lỗi bước giá nêu <b>khoảng hợp lệ bằng số thật</b> suy ra từ opening hiện tại — opening đổi thì khoảng trong message đổi theo (live). <span class="ref">BR-AU-09</span></span></li><li><span class="num">13</span><span>Lỗi cọc min 10tr: validate trên <b>số tiền suy ra</b> (floor(opening×pct)), không chỉ trên % — frame minh họa ngữ cảnh admin vừa hạ khởi điểm xuống 200.000.000 ₫ nên 3% rơi dưới sàn. <span class="ref">BR-AU-06</span></span></li><li><span class="num">14</span><span><b>Không khóa nút submit khi form sai</b> — admin được bấm để nhận tổng lỗi (box đỏ đếm số trường + traceId nếu lỗi từ server); trải nghiệm khá hơn disable âm thầm. Race: tin vừa vào phiên khác → 409 <code>CONFLICT</code>, toast đỏ, dropdown reload. <span class="ref">docs/05 §1.5</span> <span class="ref">BR-AU-02</span></span></li></ol></div><h2 id="_3-publish-thanh-cong-that-bai-—-toast-he-qua" tabindex="-1">3. Publish thành công &amp; thất bại — toast + hệ quả <a class="header-anchor" href="#_3-publish-thanh-cong-that-bai-—-toast-he-qua" aria-label="Permalink to &quot;3. Publish thành công &amp; thất bại — toast + hệ quả&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;"><span class="wf-state-label">PUBLISH THÀNH CÔNG (201 + 200)</span><div class="wf-toast ok"><b>✓ Công bố phiên DGA-2026-0012 — tin CT2-A18.05 chuyển RESERVED</b> · đăng ký mở đến 16/10/2026 09:00 (GMT+7) · đã ghi audit</div><span class="wf-state-label">PUBLISH THẤT BẠI — CHƯA ĐỦ 7 NGÀY (422)</span><div class="wf-toast danger"><b>Không thể công bố: giờ mở phải cách hiện tại tối thiểu 7 ngày</b> · phiên đã lưu DRAFT — sửa giờ mở rồi công bố lại <span class="wf-callout danger">15</span></div><span class="wf-state-label">PUBLISH THẤT BẠI — TIN KHÔNG CÒN LISTED (422 INVALID_TRANSITION)</span><div class="wf-toast warn"><b>Tin CT2-A18.05 không còn ở trạng thái LISTED</b> (chủ tin vừa rút) — chọn tin khác để công bố · đã lưu DRAFT</div><div class="wf-note">Cả 3 nhánh đều <b>không mất dữ liệu form</b>: thất bại publish → phiên vẫn được tạo DRAFT (hoặc giữ form), admin sửa rồi bấm lại — không bắt nhập lại từ đầu. DRAFT quá giờ mở mà chưa publish → nhắc chỉnh ngày (UC-11 EF-2). <span class="wf-callout">16</span></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">15</span><span>Publish fail do BR-AU-03 → server 422 <code>NOTICE_TOO_SHORT</code>; FE hiển thị toast đỏ + giữ nguyên state DRAFT vừa tạo, highlight lại field giờ mở. Không dùng message tự viết khi server đã trả message chuẩn (docs/06 §5 một nguồn). <span class="ref">endpoint 57</span> <span class="ref">UC-11 EF-1</span></span></li><li><span class="num">16</span><span>Mọi mutation màn này (create/publish) → <b>toast + audit log</b>; audit <code>AUCTION_CREATE</code> diff <code>{after}</code> full cấu hình, <code>AUCTION_PUBLISH</code> ghi notice_at — tra tại SC-49. <span class="ref">BR-ADM-01</span> <span class="ref">FR-ADM-04</span></span></li></ol></div><h2 id="_4-trang-thai-man-—-loading-submitting-sua-draft-qua-han" tabindex="-1">4. Trạng thái màn — loading / submitting / sửa DRAFT quá hạn <a class="header-anchor" href="#_4-trang-thai-man-—-loading-submitting-sua-draft-qua-han" aria-label="Permalink to &quot;4. Trạng thái màn — loading / submitting / sửa DRAFT quá hạn&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON (mở form sửa DRAFT)</span><div class="wf-card"><div class="pad wf-col"><div class="wf-skeleton" style="height:38px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><span class="wf-small">Tạo mới → form trống hiện ngay (không skeleton). Sửa DRAFT (vào từ SC-44) → skeleton tới khi fetch xong cấu hình; sidebar tóm tắt chỉ tính khi có dữ liệu.</span></div></div></div><div class="wf-col"><span class="wf-state-label">SUBMITTING — CHỐNG DOUBLE-SUBMIT</span><div class="wf-card"><div class="pad wf-col"><span class="wf-btn primary disabled block">Lưu &amp; Công bố… (đang gửi)</span><span class="wf-btn disabled block">Lưu nháp</span><span class="wf-small">Cả 2 nút + mọi input khóa khi đang gửi; ESC bị vô hiệu. Lỗi mạng → mở lại nút, giữ nguyên dữ liệu form, toast danger + traceId.</span></div></div></div><div class="wf-col"><span class="wf-state-label">DRAFT QUÁ GIỜ MỞ — CHƯA PUBLISH (UC-11 EF-2)</span><div class="wf-card"><div class="pad wf-col"><div class="wf-toast warn"><b>Giờ mở đã qua mà phiên vẫn DRAFT</b> — chỉnh lại ngày giờ rồi công bố; không publish được với startAt trong quá khứ <span class="wf-callout">17</span></div><div class="wf-input error filled">10/10/2026 09:00 (GMT+7)<span class="caret">🗓</span></div><span class="wf-field-error">Giờ mở phải ở tương lai và cách thời điểm công bố tối thiểu 7 ngày</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">17</span><span>DRAFT để quá startAt không tự hủy — admin mở lại form, banner vàng + field giờ mở lỗi, sửa ngày rồi &quot;Lưu &amp; Công bố&quot; như thường. 4-state của màn: Loading (chỉ khi sửa DRAFT) → Error (không fetch được cấu hình: hộp lỗi + traceId + Thử lại, không cho ghi đè) → Data (form) → Submitting (mục giữa). Không có Empty (form luôn có khung). <span class="ref">UC-11 EF-2</span> <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-45" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-45 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-45" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-45&quot;">​</a></h2><ul><li>[ ] Đủ field: tin (searchable select) · khởi điểm · bước giá · % cọc · % phí · giờ mở · giờ kết thúc · đóng đăng ký (readonly, có icon khóa)</li><li>[ ] Sidebar tóm tắt tính live: cọc số tiền thật (90.000.000 ₫), khoảng bước giá cho phép, phí ước tính — frame &quot;đổi opening → sidebar đổi theo&quot;</li><li>[ ] 2 frame validation: (a) giờ mở &lt; +7 ngày, (b) bước giá ngoài 1–20% — error đỏ tại field + box tổng lỗi + traceId</li><li>[ ] 3 toast: publish ok / NOTICE_TOO_SHORT / tin không còn LISTED — copy đúng docs/06 §5, không tự viết lại</li><li>[ ] 2 nút lưu phân cấp rõ: &quot;Lưu &amp; Công bố&quot; primary, &quot;Lưu nháp&quot; secondary; loading state chống double-submit</li><li>[ ] PUBLISHED-edit variant (vào từ SC-44 click dòng): form disable toàn bộ khi đã có registration ACTIVE — banner &quot;Đã có người cọc theo cấu hình này — không thể sửa (AUCTION_LOCKED)&quot;</li><li>[ ] Responsive note: desktop-priority; ≤768px sidebar tóm tắt chuyển xuống dưới form, sticky nút lưu</li><li>[ ] Không emoji icon production (🗓/🔒/✓ là placeholder vị trí); tiền format <code>1.800.000.000 ₫</code>; ngày <code>dd/MM/yyyy HH:mm</code> + GMT+7</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',18)])])}const f=a(t,[["render",c]]);export{g as __pageData,f as default};
